import binascii
from collections import Counter

def xor_decrypt(ciphertext, key):
    """Decrypts a ciphertext using a repeating-key XOR."""
    key = bytearray(key)
    ciphertext = bytearray(ciphertext)
    return bytearray([ciphertext[i] ^ key[i % len(key)] for i in range(len(ciphertext))])

def hamming_distance(s1, s2):
    """Calculate the Hamming distance between two byte strings."""
    assert len(s1) == len(s2)
    return sum(bin(b1 ^ b2).count('1') for b1, b2 in zip(s1, s2))

def average_hamming_distance(ciphertext, key_size):
    """Calculate normalized Hamming distance for a given key size."""
    chunks = [ciphertext[i:i+key_size] for i in range(0, len(ciphertext), key_size)][:4]  # Take first 4 chunks
    distances = []
    for i in range(len(chunks) - 1):
        distances.append(hamming_distance(chunks[i], chunks[i + 1]))
    return sum(distances) / (len(distances) * key_size)

def guess_key_size(ciphertext):
    """Guess most likely key size by evaluating normalized Hamming distance."""
    distances = {}
    for key_size in range(2, 17):  # Test key sizes from 2 to 16
        distances[key_size] = average_hamming_distance(ciphertext, key_size)
    return sorted(distances, key=distances.get)  # Return key sizes sorted by likelihood

def get_key(ciphertext, key_size):
    """Derive the repeating key by statistical analysis."""
    key = []
    for i in range(key_size):
        block = ciphertext[i::key_size]  # Get every i-th byte for current key size
        freq = Counter(block)
        key_byte = max(freq, key=lambda k: freq[k]) ^ ord(' ')  # Assume space as most common char
        key.append(key_byte)
    return bytearray(key)

