from itertools import cycle
import string
import sys

def xor_decrypt(ciphertext, key):
    return bytes(c ^ k for c, k in zip(ciphertext, cycle(key)))

def score_plaintext(plaintext):
    # Scoring based on common ASCII characters in readable text
    readable_chars = string.ascii_letters + string.digits + string.punctuation + ' \n\r\t'
    return sum(1 for c in plaintext if chr(c) in readable_chars)

def find_key_and_decrypt(ciphertext, max_key_length=32):
    best_plaintext = None
    best_key = None
    best_score = 0

    for key_length in range(1, max_key_length + 1):
        for key in (bytes([k]) for k in range(256)):
            candidate_key = key * key_length
            plaintext = xor_decrypt(ciphertext, candidate_key)
            score = score_plaintext(plaintext)

            if score > best_score:
                best_score = score
                best_plaintext = plaintext
                best_key = candidate_key

    return best_plaintext, best_key

